错误原因：return 位于循环内部，第一次迭代就返回。

def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def sum_even(n):
    total = 0
    for i in range(1, n + 1):
        if i % 2 == 0:
            total += i
    return total

n = int(input())
print(sum_even(n))
